"""Write the main reader's consolidated notation register (visual decisions only)."""
from pathlib import Path
import json

out=Path(__file__).resolve().parents[1]
rows=[]
def add(sign,reading,pages,evidence):
    rows.append(dict(sign=sign,reading=reading,pages=pages,evidence=evidence))

add(r'\Pi_1,\Pi_0,\Pi;\quad\widehat\Pi_1', 'Capital Pi for fundamental groups, groupoids and acting groups; each hat and index is recorded separately.', '077–100', 'Flat cap and two upright legs recur in large and small writing. Small size alone is not lowercase. All page occurrences were compared by the assigned reader; differences from the witnesses have their individual crop evidence. The component functor below is a separate notation.')
add(r'\pi_0;\quad\{\pi_0\}(E_0)', 'Component-set functor, including the braced form in (51).', '097–098', 'The annotation on 097 identifies the component functor in the topos of Pi-sets. On 098 it is applied three times in (52). These small forms resemble capital Pi: the local definition and use distinguish them from acting-group Pi, rather than shape alone.')
add(r'\Pi_1\text{ versus }\widehat\Pi_1', 'A hat is not supplied from the mathematical meaning.', '077–100', 'Unhatted source forms occur beside hatted ones, including the second groupoid in the 077 margin, path conditions and map labels on 078, groupoids on 086–090, and the lemma on 091. Local uncertainty over a hat remains local; it does not set a rule for other occurrences.')
add(r'\widehat\Pi(x_0);\quad\Pi_1(x_0);\quad\Pi', 'Arguments and missing indices remain exactly as written.', '081, 092, 097–098', 'The 081 underbrace annotation has no lower 1. The 092 torsor group has subscript 1 and x0 alone. The subgroup target in (51) and acting-group signs on 098 have no index. These have not been repaired from nearby definitions.')
