add(r'\unsure{\mathbb U|U}_{0,3};\quad U_{0,3}', 'U alphabet unresolved at the first doubled-looking specimen, plain where subsequently clear.', '083, 087–090, 100', 'The 083 left stem may be deliberate doubling or retracing. Plain U is visible on 087. Both surprising U targets on 088 remain U rather than the contextually expected curve letter.')
add(r'\Theta,\Theta^n,\Theta^\nu;\quad\widetilde\Theta,\widetilde\Theta_0', 'Crossed oval Theta, with separate powers, lift tildes and lower indices.', '090–100', 'Superscript n is written on 090–091; nu on 096. The first inserted lift mark on 093, connected upper cap on 094, prime/star on 095 and cancelled lift on 098 retain their individual doubts. No decoration is propagated into unclear ink.')
add(r'{}^u l,{}^u a,{}^u b,{}^u g_l(v)', 'Left superscript u denotes the written action.', '077–082', 'The action mark stands above-left; right-hand inverse exponents stand above-right. The position and attachment are checked in each formula, without rewriting to a different cocycle convention.')
