add(r'I\subset X_{\overline K};\quad I\cap\unsure{X_{\overline K}|X_K}\ne\varnothing', 'Main field subscript is barred; the inserted condition retains its ambiguous bar.', '100', 'The baseline bar is clear. The insertion has a short heavy mark above K that could be a live or retouched bar. The expected rational-point condition is not used to remove it. The empty-set sign is an oval with a slash, transcribed as varnothing.')

audit_updates=out/'documentation/notation_audit_updates.json'
if audit_updates.exists():
    for update in json.loads(audit_updates.read_text()):
        if 'match_sign' in update:
            matches=[row for row in rows if row['sign']==update['match_sign']]
            assert len(matches)==1, update['match_sign']
            matches[0].update(update['fields'])
        else:
            rows.append(update)
(out/'documentation/notation_final.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n')
print(len(rows),'canonical notation entries written')
